<template><div class="page-card"><div class="toolbar"><el-button v-if="canCreate" type="success" @click="openCreate">新增项目</el-button><el-button @click="load">刷新</el-button></div><el-table :data="rows"><el-table-column prop="project_name" label="项目名称" min-width="180"/><el-table-column prop="project_code" label="项目编码" min-width="160"/><el-table-column prop="role" label="我的角色" width="110"/><el-table-column prop="status" label="状态" width="100"/><el-table-column prop="description" label="说明" min-width="220"/><el-table-column label="操作" width="160"><template #default="s"><el-button link type="primary" @click="$router.push(`/projects/${s.row.project_id}`)">详情</el-button><el-button v-if="s.row.role==='OWNER'" link type="warning" @click="edit(s.row)">编辑</el-button></template></el-table-column></el-table>
<el-dialog v-model="visible" :title="form.project_id?'编辑项目':'新增项目'" width="620px"><el-form label-width="110px"><el-form-item label="所属公司"><el-select v-model="form.company_id" style="width:100%"><el-option v-for="x in platformContext.companies" :key="x.company_id" :label="x.company_name" :value="x.company_id"/></el-select></el-form-item><el-form-item label="项目名称"><el-input v-model="form.project_name"/></el-form-item><el-form-item label="项目编码"><el-input v-model="form.project_code"/></el-form-item><el-form-item label="Registry"><el-input v-model="form.registry"/></el-form-item><el-form-item label="Repository"><el-input v-model="form.repository"/></el-form-item><el-form-item label="默认分支"><el-input v-model="form.default_branch"/></el-form-item><el-form-item label="状态"><el-select v-model="form.status"><el-option label="启用" value="ENABLED"/><el-option label="停用" value="DISABLED"/></el-select></el-form-item><el-form-item label="说明"><el-input v-model="form.description" type="textarea"/></el-form-item></el-form><template #footer><el-button @click="visible=false">取消</el-button><el-button type="primary" @click="save">保存</el-button></template></el-dialog></div></template>
<script setup>import{computed,onMounted,reactive,ref}from'vue';import{ElMessage}from'element-plus';import api from'../api';import{loadPlatformContext,platformContext}from'../context';import{isAdmin}from'../auth';const rows=ref([]),visible=ref(false),form=reactive({project_id:null,company_id:null,project_code:'',project_name:'',registry:'',repository:'',default_branch:'main',status:'ENABLED',description:''});const canCreate=computed(()=>isAdmin.value||platformContext.companies.some(x=>['OWNER','ADMIN'].includes(x.role)));async function load(){rows.value=(await api.get('/projects',{params:platformContext.companyId?{company_id:platformContext.companyId}:{}})).data}function openCreate(){Object.assign(form,{project_id:null,company_id:platformContext.companyId,project_code:'',project_name:'',registry:'',repository:'',default_branch:'main',status:'ENABLED',description:''});visible.value=true}function edit(row){Object.assign(form,row);visible.value=true}async function save(){try{const payload={...form};delete payload.project_id;if(form.project_id)await api.put(`/projects/${form.project_id}`,payload);else await api.post('/projects',payload);ElMessage.success('保存成功');visible.value=false;await loadPlatformContext();load()}catch(e){ElMessage.error(e.response?.data?.detail||'保存失败')}}onMounted(load)</script>
